SELECT COUNT(DISTINCT struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR)) AS "count_result" FROM triples t0, triples t1, triples t2, triples t3, triples t4, triples t5 WHERE t0.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/likes' AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/friendOf' AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://purl.org/dc/terms/Location' AND struct_pack(kind := 0::UTINYINT, value := t3.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t3.p = 'http://xmlns.com/foaf/age' AND struct_pack(kind := 0::UTINYINT, value := t4.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t4.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/gender' AND struct_pack(kind := 0::UTINYINT, value := t5.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t5.p = 'http://xmlns.com/foaf/givenName'